//! Replays `fixtures/vcs-project-config.jsonl`, generated by
//! `rust/tools/generate_vcs_project_config_fixtures.mjs` from the original VcsProjectConfig.ts.
use std::fs;

use serde_json::Value;
use t3_vcs::{
    VcsDriverKind,
    project_config::{ConfigOperation, find_config_path, read_configured_kind, resolve_kind},
};

fn kind_name(kind: Option<VcsDriverKind>) -> &'static str {
    kind.map_or("auto", VcsDriverKind::as_str)
}

#[test]
fn config_contents_resolve_like_the_original() {
    let rows = include_str!("fixtures/vcs-project-config.jsonl");
    let mut checked = 0;
    for line in rows.lines() {
        let row: Value = serde_json::from_str(line).unwrap();
        let content = row["content"].as_str().unwrap();
        let root = tempfile::tempdir().unwrap();
        fs::create_dir(root.path().join(".t3code")).unwrap();
        let nested = root.path().join("packages/app");
        fs::create_dir_all(&nested).unwrap();
        fs::write(root.path().join(".t3code/vcs.json"), content).unwrap();

        let resolved = resolve_kind(&nested, None);
        assert_eq!(kind_name(resolved), row["kind"], "content {content:?}");

        let (path, inspect_errors) = find_config_path(&nested);
        assert!(inspect_errors.is_empty());
        let read = read_configured_kind(&nested, &path.unwrap());
        assert_eq!(
            read.is_err(),
            row["warned"].as_bool().unwrap(),
            "content {content:?}"
        );
        checked += 1;
    }
    assert_eq!(checked, 43);
}

#[test]
fn an_explicit_request_wins_over_config() {
    let root = tempfile::tempdir().unwrap();
    fs::create_dir(root.path().join(".t3code")).unwrap();
    fs::write(
        root.path().join(".t3code/vcs.json"),
        r#"{"vcs":{"kind":"git"}}"#,
    )
    .unwrap();
    assert_eq!(
        resolve_kind(root.path(), Some(VcsDriverKind::Jj)),
        Some(VcsDriverKind::Jj)
    );
    assert_eq!(resolve_kind(root.path(), None), Some(VcsDriverKind::Git));
}

#[test]
fn no_config_means_auto() {
    let root = tempfile::tempdir().unwrap();
    let nested = root.path().join("a/b");
    fs::create_dir_all(&nested).unwrap();
    assert_eq!(resolve_kind(&nested, None), None);
}

#[test]
fn an_unreadable_config_path_reports_a_read_failure_and_resolves_to_auto() {
    let root = tempfile::tempdir().unwrap();
    // A directory where the file should be: it exists, but cannot be read as a file.
    fs::create_dir_all(root.path().join(".t3code/vcs.json")).unwrap();
    let config_path = root.path().join(".t3code/vcs.json");
    let error = read_configured_kind(root.path(), &config_path).unwrap_err();
    assert_eq!(error.operation, ConfigOperation::Read);
    assert_eq!(error.config_path, config_path);
    assert_eq!(
        error.to_string(),
        format!(
            "Failed to read VCS project config at {}.",
            config_path.display()
        )
    );
    assert_eq!(resolve_kind(root.path(), None), None);
}

#[test]
fn a_nearer_config_shadows_a_parent_config() {
    let root = tempfile::tempdir().unwrap();
    let nested = root.path().join("packages/app");
    fs::create_dir_all(nested.join(".t3code")).unwrap();
    fs::create_dir_all(root.path().join(".t3code")).unwrap();
    fs::write(root.path().join(".t3code/vcs.json"), r#"{"vcsKind":"jj"}"#).unwrap();
    fs::write(nested.join(".t3code/vcs.json"), r#"{"vcsKind":"git"}"#).unwrap();
    assert_eq!(resolve_kind(&nested, None), Some(VcsDriverKind::Git));
}
